# -*- coding: utf-8 -*-
"""RevX tool knowledge for RevitBot (auto-generated — run _scan_revx_tools.py then _build_revx_knowledge.py)."""

REVX_PHRASE_KEYWORDS = ['copy state', 'crop view', 'element id', 'filled region to floor', 'filled region to toposolid', 'floor to toposolid', 'get blocks', 'height offset', 'imported cad', 'in-place to loadable', 'line pattern', 'line to detail item', 'match slope', 'material list', 'name changer', 'object outline', 'organic mound', 'override crop region', 'paste state', 'reset shape', 'rev x', 'selection box', 'server families', 'sheet export', 'surface pattern region', 'table gen', 'transfer filters', 'unused view filters', 'unused view template', 'views not on sheets']

REVX_TOOLS_KNOWLEDGE = 'REVX EXTENSION KNOWLEDGE (RevX tab in pyRevit — landscape & productivity tools).\nWhen users ask about any tool below, explain WHAT it does, WHERE to find it in the UI path, WHEN to use it, and HOW step-by-step. Include prerequisites, version notes, and troubleshooting.\n\nTOOL: Material List\nLocation in Revit: RevX tab > RevX > ACC\nUsage guide:\nOpens your Autodesk Construction Cloud (ACC) Docs material list folder in the default web browser.\nSteps: RevX tab > ACC > Material List. No model selection required.\nUse when you need the latest shared material/spec documents from ACC, not for Revit material parameters.\n---\nTOOL: Outlook\nLocation in Revit: RevX tab > RevX > ACC\nDetails and workflow:\npyRevit pushbutton script: opens Outlook Web App inbox in Google Chrome.\nWorks across all Revit versions.\n---\nTOOL: Filled Region to Floor\nLocation in Revit: RevX tab > RevX > Convert\nDetails and workflow:\nConvert selected Filled Regions <-> Floors in one click.\n\nSelect any mix of Filled Regions and Floors and run this tool - it\ninspects each selected element\'s type and converts it in the correct\ndirection automatically. No need for two separate buttons.\n\nImportant differences vs. a Floor<->Toposolid conversion:\n  - A Filled Region is a flat, VIEW-SPECIFIC detail element with no\n    Level of its own. Floor -> Filled Region needs an active view to\n    sketch into (ideally a plan/section/drafting view whose plane\n    matches the floor). Filled Region -> Floor needs a Level: if the\n    filled region\'s host view is a plan view, its associated level is\n    used automatically; otherwise you\'ll be asked to pick one.\n  - Filled Region boundaries are 2D loops on the view\'s sketch plane;\n    Floor boundaries are 3D loops on a Level plane. The curve geometry\n    transfers as-is, so double check the result if your view isn\'t\n    aligned with the target level\'s plane.\n\nNotes / assumptions:\n  - If more than one candidate Filled Region Type / Floor Type exists\n    in the project, you\'ll be asked which to convert to. With only one\n    available, it\'s used automatically. Floor Type choices exclude\n    Structural Foundation slabs.\n  - Only the boundary geometry transfers - line styles/hatch patterns\n    on the filled region and floor parameters (Comments, Mark, etc.)\n    are NOT copied automatically.\n  - Floor.Create(CurveLoop list) requires Revit 2022+. On older Revit\n    this script falls back to the legacy doc.Create.NewFloor() call.\n---\nTOOL: Filled Region to Toposolid\nLocation in Revit: RevX tab > RevX > Convert\nDetails and workflow:\nConvert selected Filled Regions <-> Toposolids in one click.\n\nSelect any mix of Filled Regions and Toposolids and run this tool - it\ninspects each selected element\'s type and converts it in the correct\ndirection automatically. No need for two separate buttons.\n\nREQUIRES REVIT 2024 OR LATER.\nToposolid is a Revit API class introduced in Revit 2024. On older\nversions this script shows a clear message and exits instead of\ncrashing.\n\nImportant differences vs. a Floor<->Toposolid conversion:\n  - A Filled Region is a flat, VIEW-SPECIFIC detail element with no\n    Level or Height Offset parameter of its own. Toposolid -> Filled\n    Region needs an active view to sketch into (ideally a plan view\n    whose plane roughly matches the toposolid). Filled Region ->\n    Toposolid needs a Level: if the filled region\'s host view is a\n    plan view, its associated level is used automatically; otherwise\n    you\'ll be asked to pick one.\n  - A Filled Region\'s boundary curves do carry a real Z coordinate\n    (from the view\'s sketch plane), even though the region displays as\n    flat 2D. This script uses that Z, relative to the chosen Level, to\n    set the new Toposolid\'s Height Offset From Level - so it doesn\'t\n    silently land flat at the level\'s exact elevation.\n\nNotes / assumptions:\n  - If more than one candidate Toposolid Type / Filled Region Type\n    exists in the project, you\'ll be asked which to convert to. With\n    only one available, it\'s used automatically.\n  - Only the boundary geometry transfers - no slope/grading data (a\n    Filled Region has none to begin with), no line styles/hatch\n    patterns, no instance parameters (Comments, Mark, etc.).\n---\nTOOL: Floor to Toposolid\nLocation in Revit: RevX tab > RevX > Convert\nDetails and workflow:\nConvert selected Floors <-> Toposolids in one click.\n\nSelect any mix of Floors and Toposolids and run this tool - it inspects\neach selected element\'s type and converts it in the correct direction\nautomatically (Floor -> Toposolid, Toposolid -> Floor). No need for two\nseparate buttons.\n\nREQUIRES REVIT 2024 OR LATER.\nToposolid is a Revit API class introduced in Revit 2024. It does not\nexist in Revit 2019-2023, so true bidirectional conversion is only\npossible on 2024+. On older versions this script shows a clear message\nand exits instead of crashing.\n\nNotes / assumptions (adjust to fit your project standards):\n  - If more than one target type exists in the project, you\'ll be asked\n    which Toposolid Type / Floor Type to convert to. If there\'s only\n    one available, it\'s used automatically with no prompt. Floor Type\n    choices exclude Structural Foundation slabs.\n  - Only the sketch boundary (footprint / shape) is transferred. Floor\n    parameters (Comments, Mark, etc.) are NOT copied automatically.\n  - Sloped/shape-edited floors: the boundary curves transfer, but\n    point-based sub-element slope edits are not - you\'ll likely need to\n    re-edit the surface on the new element for complex shapes.\n  - You choose (via a prompt) whether the original elements are deleted\n    after conversion, so you can review results before committing.\n---\nTOOL: Convert\nLocation in Revit: RevX tab > RevX > Detail Item\nDetails and workflow:\nOne-click: take the selected element (as shown in the active view),\nexport it to a temporary CAD (DWG) file, bring that CAD file into a new\nDetail Item family as native detail lines, save the family, and load it\nback into the project at the original location.\n\nThe ONLY user-facing dialogs are:\n  1. Name the new family\n  2. Choose where to save the .rfa\n\nEverything else (temp CAD export path, family template lookup, CAD import,\nline conversion, load-back, cleanup) happens silently. Non-fatal problems\nare written to the pyRevit output console instead of a blocking popup.\n---\nTOOL: Line to Detail Item\nLocation in Revit: RevX tab > RevX > Detail Item\nDetails and workflow:\nConvert a selected line/element\'s curve geometry into a new Detail Item\nfamily, let the user name it, and save it as an .rfa file.\n\nCompatible with Revit 2023, 2024, 2025, 2026 and 2027.\nThe Revit API calls used here (Transaction, CurveElement, NewDetailCurve,\nNewFamilyDocument, SaveAsOptions, LoadFamily) have been stable since well\nbefore 2023, so no version branching is needed for the API itself. The only\nthing that changes year-to-year is the folder name of the default family\ntemplates, which is handled below by trying several likely paths before\nfalling back to a manual file picker.\n\nWorks under both the IronPython2 engine (default on older pyRevit/Revit\ninstalls) and the CPython3 engine (used on newer pyRevit installs for\nRevit 2025+) - no engine-specific syntax is used.\n---\nTOOL: Dwg\nLocation in Revit: RevX tab > RevX > Export > Cad\nDetails and workflow:\nDWG Export - Pattern + Blocks merged into single file\nAuthor: Jesto Joy\n---\nTOOL: Irrigation\nLocation in Revit: RevX tab > RevX > Export > Cad\nDetails and workflow:\nDWG Export - Pattern and Blocks as SEPARATE DWG files\nAuthor: Jesto Joy\n\nExports two DWG files per view:\n  - ViewName_PAT.dwg  (pattern categories only, shape-reset)\n  - ViewName_BLK.dwg  (all other categories + annotations)\n---\nTOOL: Category\nLocation in Revit: RevX tab > RevX > Family\nDetails and workflow:\nPick a family instance in the active view, then choose a new\ncategory from an alphabetical list to re-assign the family to.\n\nWorkflow:\n  1. Click the button.\n  2. Pick a family instance (loadable family) in the open view.\n  3. A list of valid categories appears (alphabetical order).\n  4. Pick one, press \'Apply\' -> the family is opened in the\n     background, its category changed, and reloaded into the project.\n\nCompatible with Revit 2018 through 2026+ (IronPython & CPython engines).\n---\nTOOL: Name Changer\nLocation in Revit: RevX tab > RevX > Family\nDetails and workflow:\nFamily Renamer.\n\n1. Choose a category.\n2. All loadable families of that category in the project are listed.\n3. Live-preview renaming: prefix, suffix, find/replace, case change -\n   with current -> new name shown side by side.\n4. \'Edit in Notepad\' opens all checked names in Notepad, one per line:\n   edit them freely, save and close Notepad, and the edited names are\n   pulled back into the preview.\n5. Apply renames the checked families in one transaction (instant,\n   no family reload needed).\n\nCompatible with Revit 2018 through 2026+ (IronPython engines).\n---\nTOOL: Server Families\nLocation in Revit: RevX tab > RevX > Family\nDetails and workflow:\nFamily Browser – pick a Revit project, browse its loadable families by category,\n   select multiple families and load them into the current project.\n\n   Compatible: Revit 2022-2027 / pyRevit / IronPython 2.7 / CPython 3\n\n   FIXES vs original:\n   - \'Transform is not defined\' error: removed broken ElementTransformUtils approach\n   - Family copy now uses the correct method: SaveAs temp .rfa + LoadFamily()\n     This is the only cross-document family transfer method that works reliably\n     in all Revit versions without needing RevitServices or Dynamo assemblies.\n---\nTOOL: Copy State\nLocation in Revit: RevX tab > RevX > Filter > Filter.Stack\nSummary: Copy filter visibility settings and graphic overrides from the active view for use in another view or view template.\nDetails and workflow:\nCopy State - Debug color saving.\nUsage guide:\nSaves view filter graphic overrides (colors, line weights, patterns, visibility) from the active view to a JSON file (filter_data/filter_state.json under the Filter panel).\nSteps:\n  1. Open the source view where filters look correct.\n  2. RevX tab > Filter > Copy State.\n  3. Check the filters you want to copy in the dialog.\n  4. Confirm — overrides are stored for Paste State.\nTip: Copy from a view that is NOT locked by a template, or ensure the template allows filter overrides.\n---\nTOOL: Paste State\nLocation in Revit: RevX tab > RevX > Filter > Filter.Stack\nSummary: Paste saved view filter overrides to the current view/template — in the same project or another open project\nDetails and workflow:\nPaste State - Apply ALL filter overrides to active view (Template‑aware).\nUsage guide:\nApplies previously copied filter overrides onto the active view or its view template (template-aware).\nWorks within the same project or across two open projects if filter names match.\nSteps:\n  1. Run Copy State on the source view first.\n  2. Open the target view (or view whose template should receive overrides).\n  3. RevX tab > Filter > Paste State.\n  4. Choose which saved filters to apply.\nTroubleshooting: If nothing changes, the view template may control filters — the tool writes to the template when needed. Missing filters in the target project must exist or be transferred with Transfer Filters.\n---\nTOOL: Transfer Filters\nLocation in Revit: RevX tab > RevX > Filter > Filter.Stack\nRibbon button name: Transfer\nSummary: Copy view filter definitions (categories, rules, names) from one open project to another\nDetails and workflow:\nTransfer Filters - Cross-Project Parameter Filter Transfer\nUsage guide:\nCopies view filter definitions (rules, categories, names) from one open Revit project to another.\nSteps:\n  1. Have source and target projects open.\n  2. RevX tab > Filter > Transfer.\n  3. Pick source project and filters to copy.\n  4. Pick target project — filters are recreated there.\nUse before Paste State when the target project does not contain the same filter names.\n---\nTOOL: Height offset\nLocation in Revit: RevX tab > RevX > Floor\nUsage guide:\nResets or adjusts floor height offset for selected floors (RevX tab > Floor > Height offset).\nSelect floors first, then run — read the dialog for reset vs offset behavior.\n---\nTOOL: Offset\nLocation in Revit: RevX tab > RevX > Floor\nSummary: Resize Floors, Roofs, Ceilings, and Toposolids by applying an inward or outward boundary offset.\n---\nTOOL: Reset Shape\nLocation in Revit: RevX tab > RevX > Floor\nSummary: Reset shape-edited floors back to their original flat condition by removing all slab shape modifications.\nDetails and workflow:\nReset shape of selected floors with detailed feedback\n---\nTOOL: Get Blocks\nLocation in Revit: RevX tab > RevX > Landscape > 01\nSummary: Place families from AutoCAD POINT data\nDetails and workflow:\nGet Blocks - Place Families from AutoCAD POINT Data\nUsage guide:\nPlaces Revit families at locations from AutoCAD POINT entities.\nSteps:\n  1. Ensure CAD import/link contains POINT objects with block names matching family types.\n  2. RevX tab > Landscape > Get Blocks.\n  3. Pick CAD source, family mapping, and level.\n  4. Run placement.\nUse for planting/furniture layouts exported from CAD as points.\n---\nTOOL: Surface Pattern Region\nLocation in Revit: RevX tab > RevX > Landscape > 01\nRibbon button name: Object Outline\nSummary: Generate filled regions with material-based surface patterns\nDetails and workflow:\nFloorToFilledRegion.py  (v7 - per-element transactions + arc tessellation)\n-------------------------------------------------------------------------------\nPyRevit Script: Creates filled regions from the topmost compound-structure\nlayer of Floors, Roofs, Ceilings, and Toposolids.\n\nFilledRegionType naming rule:\n  "<ElementTypeName> (Layout)"\n  e.g.  "LA_Paving type-IF1"  ->  "LA_Paving type-IF1 (Layout)"\n\nCompatible: Revit 2018-2027+  |  IronPython 2.7 (PyRevit)\n\nChanges in v7 (vs v6):\n  - Each element now processed in its OWN sub-transaction so a Revit\n    sketch-constraint failure on one floor cannot crash all others\n  - Arc/curve tessellation fallback: if a loop with arcs causes a\n    constraint error, arcs are converted to short line segments\n    (tessellate_loop_to_lines) and retried - fixes curved floors in Revit 2026\n  - Three-tier placement strategy per element:\n      Tier 1: all loops together with original curves\n      Tier 2: all loops together with arcs tessellated to lines\n      Tier 3: each loop individually (tessellated) as last resort\n---\nTOOL: Match Slope\nLocation in Revit: RevX tab > RevX > Landscape > 02\nSummary: Transfer slab shape from source to target elements\nDetails and workflow:\nMap each grid cell to list of triangle indices whose bbox overlaps it.\nUsage guide:\nTransfers shape/slope from a source floor/toposolid to target elements (landscape grading).\nSteps:\n  1. RevX tab > Landscape > Match Slope.\n  2. Pick source element with the desired slope/shape.\n  3. Pick target element(s) to receive that shape.\nTargets must support shape editing (floors/toposolids). Complex meshes may need manual touch-up.\n---\nTOOL: Organic Mound\nLocation in Revit: RevX tab > RevX > Landscape > 02\nRibbon button name: Toposolid\nSummary: Creates an organic terrain mound (Toposolid / TopographySurface) from selected boundary model lines with smooth natural grading.\nDetails and workflow:\nOrganicMound.py\n---------------\nCreates a smooth organic toposolid/topography mound from selected\nboundary model lines.\n\nModes:\n  Slope Mode      - height derived from slope ratio (1:N)\n  Max Height Mode - user enters height in MILLIMETRES; converted to feet\n                    internally (Revit internal unit = feet)\n\nSmoothing uses a quintic smooth-step blended with a Gaussian falloff\nfor a natural real-world hill profile with no flat top, no centre spike,\nand a gentle zero-gradient landing at the boundary edge.\n\nCompatible: Revit 2018-2025+  |  IronPython 2.7 (PyRevit)\n---\nTOOL: Custom\nLocation in Revit: RevX tab > RevX > Link\nDetails and workflow:\nCopy RVT Link display overrides from one view to one or more views.\n\nCopies:\n- Link visibility type (Custom)\n- ALL category overrides (Model, Annotation, Analytical, Import)\n  including visibility, halftone, line weight, color, pattern, transparency\n- Category visibility (on/off)\n\nHandles views with or without view templates:\n- If target has no template (or template doesn\'t control RVT Links): writes to view\n- If target has a template controlling RVT Links: writes to the template directly\n\nRequires Revit 2018+ (View.GetLinkOverrides / SetLinkOverrides API).\nUsage guide:\nCopies RVT link visibility and graphic overrides from one view to other views.\nSteps:\n  1. Set link overrides in a source view (Custom link display).\n  2. RevX tab > Link > Custom.\n  3. Pick source view, then target view(s).\nHandles view templates that control link visibility.\n---\nTOOL: Element ID\nLocation in Revit: RevX tab > RevX > Link\nDetails and workflow:\nRobust type name extractor for all Revit versions (2023–2026)\nUsage guide:\nShows robust type/element identification for linked or selected elements (RevX tab > Link > Element ID).\nUse when debugging links or writing schedules that need stable type names.\n---\nTOOL: Selection Box\nLocation in Revit: RevX tab > RevX > Link\nUsage guide:\nLink panel utility for selection/box workflows around linked models — run from RevX tab > Link > Selection Box and follow on-screen prompts.\n---\nTOOL: Health\nLocation in Revit: RevX tab > RevX > Model Health\nUsage guide:\nModel Health dashboard — scans the project for common issues (unused views/templates/filters, imports, warnings, etc.) and offers cleanup actions from one window.\nSteps:\n  1. RevX tab > Model Health > Health.\n  2. Review each category in the dialog.\n  3. Use purge/delete buttons per row where offered — read warnings before deleting.\nUse before issuing models; pair with Wipe tools for targeted cleanup.\n---\nTOOL: Pin\nLocation in Revit: RevX tab > RevX > Model Health\nUsage guide:\nBulk pin/unpin elements or views per Model Health workflows — open from RevX tab > Model Health > Pin.\nUse to protect approved geometry or views from accidental moves; unpin before editing pinned items.\n---\nTOOL: Imported Cad\nLocation in Revit: RevX tab > RevX > Model Health > Wipe\nDetails and workflow:\nGet all imported CAD files (not linked) in the project.\nUsage guide:\nLists imported CAD instances (not links) and helps remove them from the project.\nRevX tab > Model Health > Wipe > Imported Cad. Review list before delete — prefer removing unused imports to reduce file size and warnings.\n---\nTOOL: Line Pattern\nLocation in Revit: RevX tab > RevX > Model Health > Wipe\nUsage guide:\nModel Health wipe tool for unused or problematic line patterns. RevX tab > Model Health > Wipe > Line Pattern.\n---\nTOOL: Unused View Filters\nLocation in Revit: RevX tab > RevX > Model Health > Wipe\nDetails and workflow:\nGet all view filters that are not applied to any view.\nUsage guide:\nFinds view filters not used by any view. RevX tab > Model Health > Wipe > Unused View Filters.\nDelete only after confirming filters are not needed for future views.\n---\nTOOL: Unused View Template\nLocation in Revit: RevX tab > RevX > Model Health > Wipe\nDetails and workflow:\nGet all view templates that are not applied to any view.\nUsage guide:\nFinds view templates not assigned to any view. RevX tab > Model Health > Wipe > Unused View Template.\n---\nTOOL: Views not on Sheets\nLocation in Revit: RevX tab > RevX > Model Health > Wipe\nDetails and workflow:\nGet all view IDs that are placed on sheets.\nUsage guide:\nReports views that are not placed on sheets (or related cleanup — check dialog text).\nRevX tab > Model Health > Wipe > Views not on Sheets. Useful before archiving views.\n---\nTOOL: Excel\nLocation in Revit: RevX tab > RevX > Schedule\nDetails and workflow:\nExport Revit Schedule to Excel - Match Schedule Exactly\n\nPreserves formatting, colors, images, borders, row/column sizes\nand merged cells from Revit schedules.\n\nCompatible: Revit 2024, 2025, 2026, 2027\nRequires: Microsoft Excel installed\nUsage guide:\nExports the active schedule view to Excel preserving layout, colors, borders, merges, and images.\nSteps:\n  1. Open the schedule view in Revit.\n  2. RevX tab > Schedule > Excel.\n  3. Choose output path — requires Microsoft Excel installed (Revit 2024–2027).\n---\nTOOL: Table Gen\nLocation in Revit: RevX tab > RevX > Schedule\nDetails and workflow:\nTableGen - Excel/CSV to native Revit Schedule.\nUsage guide:\nImports Excel or CSV data and creates a native Revit schedule/key schedule in the project.\nSteps:\n  1. Prepare Excel/CSV with column headers matching desired schedule fields.\n  2. RevX tab > Schedule > Table Gen.\n  3. Pick the file, map columns to Revit fields, confirm schedule type.\n  4. Place or open the new schedule view.\nBest for key schedules and lookup tables; verify units and data types match Revit parameters.\n---\nTOOL: Sheet Export\nLocation in Revit: RevX tab > RevX > Sheets\nRibbon button name: Export\nSummary: Batch export sheets and views to PDF, DWG, DGN, DWF, NWC, IFC and images with custom file naming rules, saved naming presets and export sets.\nDetails and workflow:\nSheet Expor .\n\nSelection -> Format -> Create workflow with custom file naming.\nExports PDF / DWG / DGN / DWF / NWC / IFC / IMG.\n\nCompatible with Revit 2024, 2025, 2026, 2027 (IronPython 2.7, 3.x and CPython).\nUsage guide:\nBatch export sheets and/or views to PDF, DWG, DGN, DWF, NWC, IFC, or image formats with custom naming.\nWorkflow: Selection (pick sheets/views) -> Format (choose export type and options) -> Create (run batch).\nSteps:\n  1. RevX tab > Sheets > Sheet Export.\n  2. Select sheets/views in the UI (or use saved export sets if available).\n  3. Choose format (PDF, DWG, etc.) and naming rules / presets.\n  4. Set output folder and run Create.\nRequires Revit 2024–2027. Naming presets can combine sheet number, name, revision, and custom tokens.\n---\nTOOL: Parameters\nLocation in Revit: RevX tab > RevX > Sheets\nDetails and workflow:\nEdit Title Block Instance Parameters\nAuthor: Jesto Joy\n\nWorks on Revit 2024, 2025, 2026, 2027\nUsage guide:\nEdit title block instance parameters on sheets in bulk.\nSteps:\n  1. RevX tab > Sheets > Parameters.\n  2. Select sheets or title blocks in the UI.\n  3. Edit shared/instance parameters (sheet number, issue date, etc.) and apply.\nWorks on Revit 2024–2027.\n---\nTOOL: Override Crop Region\nLocation in Revit: RevX tab > RevX > Tools\nRibbon button name: Crop View\nSummary: Change the crop region line style and lineweight for multiple views at once.\nDetails and workflow:\nOverride Crop Region Line Pattern and Lineweight for Selected View Types.\n   Finds each view\'s crop viewer element and applies per-view element overrides.\n---\nTOOL: In-Place to Loadable\nLocation in Revit: RevX tab > RevX > Tools\nSummary: Convert an in-place family into a loadable family while preserving its geometry, category, and placement.\nDetails and workflow:\nConvert In-Place Family to Loadable Family\n========================================\nPicks an in-place family instance, builds a loadable .rfa from its geometry,\nsaves it to a temp folder, loads it back, and places it in the same location.\n\nUses FreeFormElement geometry extraction (Revit 2018+).\n\nCompatible: Revit 2018-2026+  |  IronPython 2.7 / CPython 3.x (pyRevit)\n\nChangelog vs prior version\n--------------------------\n* ElementId.IntegerValue  → version-safe get_element_id_value() helper\n  (IntegerValue removed / throws on 64-bit IDs in Revit 2024+/2026)\n* DisplayUnitSystem       → version-safe is_metric_project() with ForgeTypeId\n  fallback (DisplayUnitSystem deprecated Revit 2022, gone in some builds)\n* OpenDocumentFile(str)   → wrapped in try/except; ModelPath overload tried first\n* IFamilyLoadOptions      → extra guard added for CPython 3 / newer pyRevit\n* FamilyManager.Types     → safe iteration via list() conversion\n* ElementId(int)          → never constructed directly; all ids come from API\n* rename_family_type      → safe iteration + commit guard\n---\nTOOL: Para\nLocation in Revit: RevX tab > RevX > Tools\nDetails and workflow:\nParameter Manager - A comprehensive parameter management tool for Revit.\nUsage guide:\nParameter Manager — browse and edit shared, project, and family parameters from one window.\nSteps:\n  1. RevX tab > Tools > Para (Parameter Manager).\n  2. Use tabs/trees to switch between project parameters, shared parameters, and family parameters.\n  3. Add, rename, bind, or remove parameters as allowed by Revit rules.\n  4. Apply changes — some edits require saving the project or reloading families.\nUse for bulk parameter cleanup; always coordinate shared parameter files with your BIM lead.\n---\nTOOL: Elevation\nLocation in Revit: RevX tab > RevX > Toposolid\nDetails and workflow:\nThis tool elevates selected Revit model lines by a user-defined vertical offset.The tool is useful for quickly adjusting elevation of model lines without manual repositioning. It ensures unit-safe conversion and applies changes within a single transaction for consistency.\n---\nTOOL: Mound\nLocation in Revit: RevX tab > RevX > Toposolid\nDetails and workflow:\nExtract geometry curve from any line‑type element.\n---'


def get_revx_knowledge_text():
    return REVX_TOOLS_KNOWLEDGE


def mentions_revx(message):
    if not message:
        return False
    msg = message.lower()
    if "revx" in msg or "rev x" in msg:
        return True
    for kw in REVX_PHRASE_KEYWORDS:
        if kw in msg:
            return True
    return False
